<template><div class="playlist-folders"><button class="folders-manage" @click="create">Новая папка <span>+</span></button><section v-for="folder in folders.items" :key="folder.id"><div class="folder-head"><button :aria-expanded="expanded.has(folder.id)" @click="toggle(folder.id)"><span>{{folder.icon||'📁'}}</span><strong>{{folder.name}}</strong><small>{{visible(folder).length}}</small><Icon :name="expanded.has(folder.id)?'chevronDown':'chevronRight'" :size="12"/></button><button class="folder-edit" :aria-label="`Изменить папку ${folder.name}`" @click="edit(folder)">…</button></div><div v-if="expanded.has(folder.id)"><button v-for="pl in visible(folder)" :key="pl.kind" class="folder-playlist" @click="router.push(`/playlists/${pl.kind}`)"><img v-if="pl.cover_url" :src="pl.cover_url" alt=""/><Icon v-else name="queue" :size="18"/><span>{{pl.title}}</span></button></div></section><q-dialog v-model="dialog"><div class="folder-dialog"><header><h2>{{editing?'Папка':'Новая папка'}}</h2><button class="icon-btn" aria-label="Закрыть папку" @click="dialog=false"><Icon name="close" :size="18"/></button></header><div class="folder-name"><EmojiButton :value="icon" @select="icon=$event"/><input v-model="name" placeholder="Название папки" aria-label="Название папки" maxlength="60"/></div><p class="faint t-12">Папки хранятся на этом компьютере.</p><div class="folder-choices"><label v-for="pl in library.visiblePlaylists" :key="pl.kind"><input v-model="selected" type="checkbox" :value="pl.kind"/><span>{{pl.title}}</span></label><p v-if="!library.visiblePlaylists.length" class="dim">Пока нет плейлистов.</p></div><footer><button v-if="editing" class="btn" @click="remove">Удалить папку</button><button class="btn btn-solid" :disabled="!name.trim()" @click="save">Сохранить</button></footer></div></q-dialog></div></template>
<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import Icon from '@/components/Icon.vue';import EmojiButton from '@/components/EmojiButton.vue';import {usePlaylistFoldersStore} from '@/stores/playlistFolders';import {useLibraryStore} from '@/stores/library';import type {PlaylistFolder} from '@/lib/playlistFolders';const router=useRouter(),folders=usePlaylistFoldersStore(),library=useLibraryStore();const dialog=ref(false),editing=ref(''),name=ref(''),icon=ref('📁'),selected=ref<number[]>([]),expanded=ref(new Set<string>());const visible=(f:PlaylistFolder)=>library.visiblePlaylists.filter(p=>f.kinds.includes(p.kind));function toggle(id:string){if(expanded.value.has(id))expanded.value.delete(id);else expanded.value.add(id);}function create(){editing.value='';name.value='';icon.value='📁';selected.value=[];dialog.value=true;}function edit(f:PlaylistFolder){editing.value=f.id;name.value=f.name;icon.value=f.icon;selected.value=[...f.kinds];dialog.value=true;}function save(){const id=editing.value||crypto.randomUUID();if(folders.save({id,name:name.value.trim(),icon:icon.value,kinds:selected.value})){expanded.value.add(id);dialog.value=false;}}function remove(){if(folders.remove(editing.value))dialog.value=false;}</script>
<style scoped>.folders-manage{display:flex;justify-content:space-between;width:100%;padding:9px 18px;border:0;background:none;color:var(--fg-dim);font:inherit;font-size:11px;cursor:pointer}.folders-manage:hover{color:var(--fg)}.folder-head{display:flex;align-items:center;padding:0 9px}.folder-head>button:first-child{display:flex;align-items:center;gap:8px;min-width:0;flex:1;padding:9px;border:0;background:transparent;color:var(--fg);font:inherit;cursor:pointer}.folder-head strong{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:left;font-size:12px;font-weight:500}.folder-head small{font-size:10px;color:var(--fg-dim)}.folder-edit{border:0;background:none;color:var(--fg-dim);cursor:pointer}.folder-playlist{display:flex;align-items:center;gap:8px;width:100%;padding:7px 18px 7px 34px;background:none;border:0;color:var(--fg-dim);font:inherit;font-size:12px;cursor:pointer;text-align:left}.folder-playlist:hover{background:var(--hover);color:var(--fg)}.folder-playlist img{width:25px;height:25px;border-radius:4px;object-fit:cover}.folder-playlist span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.folder-dialog{width:480px;max-width:calc(100vw - 32px);padding:22px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--fg)}header,footer,.folder-name{display:flex;align-items:center;gap:12px}header{justify-content:space-between;margin-bottom:18px}header h2{font-size:21px;margin:0}.folder-name input{min-width:0;flex:1;padding:10px;border:1px solid var(--line);border-radius:7px;background:var(--bg);color:var(--fg);font:inherit}.folder-choices{max-height:260px;overflow:auto;display:grid;gap:12px;margin:18px 0}.folder-choices label{display:flex;align-items:center;gap:10px;font-size:13px}.folder-choices input{accent-color:var(--accent)}footer{justify-content:flex-end}</style>
